def Condition( modeldata, **kwargs ):
	Heroes = modeldata.Heroes
	Buildings = modeldata.Buildings
	Lord = modeldata.Lord
	result = 0
	for hero in Heroes:
		result=0
		for talent in hero.TalentSets[hero.ActiveTalentSet].Talents:
			if  not talent.IsDefaultForHero(hero.PersistentId):
				return 1
			if  not hero.IsTalentDefault(talent.PersistentId, result, hero.ActiveTalentSet):
				return 1
			result+=1
	return 0

